    hdfsComponents.put("DATANODE", dataNode);
    hdfsComponents.put("ZKFC", zkfc);
    Mockito.when(hdfsService.getServiceComponents()).thenReturn(hdfsComponents);
    // TEZ
    Map<String, ServiceComponent> tezComponents = new HashMap<>();
